fn contains_z(s: &str) -> bool {
    // Iterate over Unicode scalar values (chars) in the string
    for ch in s.chars() {
        // Check if the character is 'z' or 'Z'
        if ch == 'z' || ch == 'Z' {
            return true;
        }
    }
    // If we never saw a 'z' or 'Z', return false
    false
}

